from taf.internal.aliasing import aliasing_scope
import taf.internal.robot_typecasts as robot_typecasts
from taf.gnb.oam.ne3s.ws.facade import NE3SClient


class ws(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope("connection", NE3SClient, name=__name__)

    def configure_connection(self,
                             address,
                             port=None,
                             username=None,
                             password=None,
                             netact_server_address=None,
                             netact_server_port=None,
                             manager_id=None,
                             alias=None,
                             debug=False,
                             debug_log_path=None,
                             netact_version='v5G20B'
                             ):
        """
        Note that consumer_url should be an url that is accessible by the agent.

        :param address: address ie. 192.168.255.129 or http://192.168.255.129 , https://192.168.255.129
        :param port: defaults to 8080
        :param username: defaults to "wsuser"
        :param password: defaults to "wspassword"
        :param netact_server_address: defaults to "http://192.168.255.126"
        :param netact_server_port: defaults to 8088
        :param manager_id: defaults to "EMSsim"
        :param str alias: name of returned connection, if not given, default alias used
        :param bool debug: should debug mode be on or off
        :param str debug_log_path: filepath where debug log should be saved
        :param str netact_version: Name of netact version, i.e. v5G19A or v5G20B. Set to the newest by default.
        Available releases: ['v5G19A', 'v5G20B']. If user expects stability from the library, always specify release
        version in the code.
        :raises UnexpectedResponse if the server answered with status code
                other than 200
        :return: server response to the completeRegistration request
        """

        ne3s_client = NE3SClient(
            address=address,
            port=port,
            username=username,
            password=password,
            netact_server_address=netact_server_address,
            netact_server_port=netact_server_port,
            manager_id=manager_id,
            name=alias,
            debug=debug,
            debug_log_path=debug_log_path,
            netact_version=netact_version
        )
        self.store.add(ne3s_client, alias)

        return ne3s_client

    @lookup_handler.implicit_lookup
    def connect(self, connection=None):
        """
        Establish a connection between Manager (OAM) and NE3S Agent.
        It sends three messages: startRegistration, completeRegistration
        and startSession.
        :param str connection: alias of connection, if not given default connection used
        """
        return connection.connect()

    @lookup_handler.implicit_lookup
    def update_software(self,
                        bts_sw_path,
                        adaptation_version=None,
                        timeout='20 min',
                        connection=None):
        """
        Provision operation combines the download, validation and activation
        of the plan into one asynchronous operation.

        Session must be already established.

        :param bts_sw_path: path to a software package zip (the only
                            catalog in unzipped file should be named 'bts_sw')
        :param adaptation_version: defaults to "MRBTS-1900"
        :param timeout: can be given as integer, float or in Robot Framework time format
        :param str connection: alias of connection, if not given default connection used
        :raises UnexpectedResponse if the server answered with status code
                other than 200
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        return connection.update_software(bts_sw_path=bts_sw_path,
                                          adaptation_version=adaptation_version,
                                          timeout=timeout)

    @lookup_handler.implicit_lookup
    def set_managed_object_parameter(self, class_name, dist_name, version_name,
                                     param_changes, timeout=720.0, connection=None):
        """
        Change value of parameter from managed object. If parameter change indicates site reset
        then it may occur before or after this keyword.
        :param str class_name: class name of managed object that is parent of parameter
        :param str dist_name: dist name of managed object that is parent of parameter
        :param str version_name: version name of managed object that is parent of parameter
        :param dict param_changes: dictionary with parameter name, new value and it's location
               if it's stored in list or item.
                Examples

                ::

                    parameter in scf:
                        <managedObject class="com.nokia.srbts:MRBTS" version="SBTS5G19_1811_010"
                        distName="MRBTS-1900" operation="update">
                          <p name="btsName">CLOUD_BTS_NAME</p>
                        </managedObject>
                    dictionary:
                        {'btsName': 'CLOUD_BTS_NAME'}

                    parameter in scf:
                        <managedObject version="NRBTS5G19B_1907_200" operation="create"
                        distName="MRBTS-1900/NRBTS-1/NRDU-1" class="com.nokia.srbts.nrbts:NRDU">
                          <list name="f1Cplane">
                            <item>
                                <p name="ipV4AddressDN1">MRBTS-1900/TNLSVC-1/TNL-4/IPNO-1/IPIF-1/IPADDRESSV4-1</p>
                            </item>
                          </list>
                        </managedObject>
                    dictionary:
                        {'f1Cplane':[{'ipV4AddressDN1': 'MRBTS-1900/TNLSVC-1/TNL-4/IPNO-1/IPIF-1/IPADDRESSV4-1'}]}

                    parameter in scf:
                        <managedObject version="NRBTS5G19B_1907_200" operation="create"
                        distName="MRBTS-1900/NRBTS-1/NRCELL-1" class="com.nokia.srbts.nrbts:NRCELL">
                          <list name="frRefList">
                            <p>FR-1</p>
                          </list>
                        </managedObject>
                    dictionary:
                        {'frRefList':['FR-1']}

                    Note that in lists without items the order of parameters matters.

        :param float timeout: timeout in seconds for keyword execution, defaults to 720.0
        :param str connection: alias of connection, if not given default connection used
        :raises ProvisioningFailed: when error occured, eg. validation fails
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        return connection.set_managed_object_parameter(class_name=class_name, dist_name=dist_name,
                                                       version_name=version_name, param_changes=param_changes,
                                                       timeout=timeout)

    @lookup_handler.implicit_lookup
    def set_parameter_by_scf(self, scf_path, timeout=720.0, connection=None):
        """
        Change parameters by delta scf or scf. If parameter change indicates site reset
        then it may occur before or after this keyword.
        :param str scf_path: path to delta scf or scf file
        :param float timeout: timeout in seconds for keyword execution, defaults to 720.0
        :param str connection: alias of connection, if not given default connection used
        :raises ProvisioningFailed: when error occured, eg. validation fails
        :raises ProvisioningPartiallyFailed: when some parameters change succeeded and some failed.
                Check notifications in logs for more details.
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        return connection.set_parameter_by_scf(scf_path, timeout)

    @lookup_handler.implicit_lookup
    def get_current_plan(self, file_path, timeout=120, connection=None):
        """
        Saves Current Plan of connected NodeB to file under file_path

        :param str file_path: path where current plan will be saved
        :param float timeout: timeout in seconds for keyword execution, defaults to 120
        :param str connection: alias of connection, if not given default connection used
        :raises OperationTimeout: when no information was provided by the Node B
        :raises OperationFailed: when error occurred and no information could be requested
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        return connection.get_current_plan(file_path=file_path, timeout=timeout)

    @lookup_handler.implicit_lookup
    def get_active_software_version(self, timeout=120, connection=None):
        """
        Get Active Partition Software Version of connected NodeB

        :param float timeout: timeout in seconds for keyword execution, defaults to 120
        :param str connection: alias of connection, if not given default connection used
        :raises OperationTimeout: when no information was provided by the Node B
        :raises OperationFailed: when error occurred and no information could be requested
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        return connection.get_active_software_version(timeout=timeout)

    @lookup_handler.implicit_lookup
    def get_active_faults(self, connection=None, timeout=30):
        """
        Gets active faults
        :param str connection: alias of connection, if not given default connection used
        :param float timeout: timeout for getting notification from server
        :return: list with alarms
        """
        return connection.get_active_faults(timeout=timeout)

    @lookup_handler.implicit_lookup
    def get_audit_trail_logs(
            self,
            destination_path,
            adaptation_version="MRBTS-1900",
            logs_age="10 days",
            timeout=600,
            connection=None):
        """
        Saves audit trail logs in given path
        :param str destination_path: ATL will be saved to this path
        :param str adaptation_version: defaults to "MRBTS-1900"
        :param str logs_age: start collecting logs from specified time difference in past, defaults to "10 days";
        can be given as integer, float or in Robot Framework time format
        :param str connection: alias of connection, if not given default connection used
        :param str timeout: timeout for getting notification from server, defaults to 10 minutes;
        can be given as integer, float or in Robot Framework time format
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        logs_age = robot_typecasts.time_to_seconds(logs_age)
        return connection.get_audit_trail_logs(
            destination_path=destination_path,
            adaptation_version=adaptation_version,
            logs_age_in_seconds=logs_age,
            timeout=timeout)

    @lookup_handler.implicit_lookup
    def activate_pm_reporting(self, class_name, dist_name, version_name, collection_interval=None,
                              reporting_interval="15min", timeout=300.0, connection=None):
        """
        Enables pm reporting on BTS and *prepares* the library to collect the PM report.
        Use fetch_latest_pm_report to save the report to a file.
        See `set_managed_object_parameter` documentation for exceptions that can be raised.
        :param str class_name: class name of pm managed object, for example: com.nokia.srbts.mnl:PMCADM
        :param str dist_name: dist name of pm managed object, for example: MRBTS-10191/MNL-1/MNLENT-1/PMCADM-1
        :param str version_name: version name of pm managed object, for example: MNL5GC19A_1904_002
        :param str collection_interval: Used only in netact version 'v5G19A'. Supported values: 5s, 10s, 30s, 60s.
        Defaults to None
        :param str reporting_interval: supported values: 5min 15min 30min 60min. Defaults to 15min
        :param str connection: alias of connection, if not given default connection used
        :param float timeout: timeout in seconds for keyword execution, defaults to 300.0
        :return: pm_update_stream
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        return connection.activate_pm_reporting(class_name, dist_name, version_name, collection_interval,
                                                reporting_interval, timeout)

    @lookup_handler.implicit_lookup
    def fetch_latest_pm_report(self, pm_file_path, timeout=720.0, connection=None):
        """
        Saves gzip file with latest pm report.
        :param str pm_file_path: path where .gzip file will be saved
        :param float timeout: timeout for getting pm report from the server, defaults to 720
        :param str connection: alias of connection, if not given default connection used
        :raises PmReportingNotActive: when `activate_pm_reporting` was not called before this keyword execution
        :return:
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        return connection.fetch_latest_pm_report(pm_file_path, timeout)

    @lookup_handler.implicit_lookup
    def install_certificate(self, cert_dist_name, path_to_cert, timeout=400, connection=None):
        """
        Installs certificate on BTS.

        :param str cert_dist_name: Dist name where certificate should be installed.
        :param str path_to_cert: Path to a local file that contains the PEM certificate.
        :param float timeout: timeout for installing certificate on BTS, defaults to 400.
        :param str connection: Alias of connection, if not given default connection used.
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        return connection.install_certificate(cert_dist_name=cert_dist_name,
                                              path_to_cert=path_to_cert,
                                              timeout=timeout)

    @lookup_handler.implicit_lookup
    def delete_certificate(self, cert_dist_name, cert_fingerprint, timeout=200, connection=None):
        """
        Removes certificate by provided fingerprint.

        :param str cert_dist_name: Dist name from which the certificate should be removed.
        :param str cert_fingerprint: Fingerprint needed to identify proper certificate.
        :param float timeout: timeout for removing certificate on BTS, defaults to 200.
        :param str connection: Alias of connection, if not given default connection used.
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        return connection.delete_certificate(cert_dist_name=cert_dist_name,
                                             cert_fingerprint=cert_fingerprint,
                                             timeout=timeout)

    @lookup_handler.implicit_lookup
    def initialize_certificate(self, dist_name, server_type=None, timeout=400, connection=None):
        """
        Initialize CMP on BTS.

        :param str dist_name: Dist name of the certificate, e.g.: "MRBTS-50243/CERTH-1/CMP-1".
        :param str server_type: Certificate type, allowed values: ``RSA`` or ``ECDSA``.
            ``None`` is set by default, means that ``server_type`` will not be set in order
            to keep backward compatibility with the older SW releases that doesn't support it.
        :param float timeout: timeout for the operation, defaults to 400.
        :param str connection: Alias of connection, if not given default connection used.
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        return connection.initialize_certificate(dist_name=dist_name, server_type=server_type, timeout=timeout)

    @lookup_handler.implicit_lookup
    def update_certificate(self, dist_name, server_type=None, timeout=400, connection=None):
        """
        Update CMP key on BTS.

        :param str dist_name: Dist name of the certificate, e.g.: "MRBTS-50243/CERTH-1/CMP-1".
        :param str server_type: Certificate type, allowed values: ``RSA`` or ``ECDSA``.
            ``None`` is set by default, means that ``server_type`` will not be set in order
            to keep backward compatibility with the older SW releases that doesn't support it.
        :param float timeout: timeout for the operation, defaults to 400.
        :param str connection: Alias of connection, if not given default connection used.
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        return connection.update_certificate(dist_name=dist_name, server_type=server_type, timeout=timeout)

    @lookup_handler.implicit_lookup
    def update_certificate_revocation_list(self, dist_name, timeout=400, connection=None):
        """
        Update certificate revocation list on BTS.

        :param str dist_name: Dist name of the CRLH, e.g.: "MRBTS-50243/CERTH-1/CRLH-1".
        :param float timeout: timeout for the operation, defaults to 400.
        :param str connection: Alias of connection, if not given default connection used.
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        return connection.update_certificate_revocation_list(dist_name=dist_name, timeout=timeout)

    @lookup_handler.implicit_lookup
    def configure_cmp_server(self, dist_name, psk, ref_number, server_type=None, timeout=400, connection=None):
        """
        Add pre-shared key and reference number to CMP settings.

        :param str dist_name: Dist name of the CRLH, e.g.: "MRBTS-50243/CERTH-1/CRLH-1".
        :param str psk: pre-shared key.
        :param int ref_number: reference number
        :param str server_type: Certificate type, allowed values: ``RSA`` or ``ECDSA``.
            ``None`` is set by default, means that ``server_type`` will not be set in order
            to keep backward compatibility with the older SW releases that doesn't support it.
        :param float timeout: timeout for the operation, defaults to 400.
        :param str connection: Alias of connection, if not given default connection used.
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        return connection.configure_cmp_server(dist_name=dist_name, psk=psk, ref_number=ref_number,
                                               server_type=server_type, timeout=timeout)

    @lookup_handler.implicit_lookup
    def set_local_account(self, adaptation_version, user_type, username, password, timeout=400,
                          connection=None):

        """
        Set arbitrary local account's name and password

        :param str adaptation_version: eg. "MRBTS-50211"
        :param str user_type: eg. "BTSApplication"
        :param str username:
        :param str password:
        :param float timeout: timeout for the operation, defaults to 400.
        """
        return connection.set_local_account(adaptation_version, user_type, username, password, timeout)

    @lookup_handler.implicit_lookup
    def unregister(self, connection=None):
        """
        Closes connection.

        :param str connection: alias of connection, if not given default connection used
        """
        return connection.unregister()

    @lookup_handler.implicit_lookup
    def teardown_all(self, connection=None):
        """
        Closes all servers, for all connections.

        :param str connection: alias of connection, if not given default connection used
        """
        return connection.teardown_all()
